import {Evolution} from './evolution.js';
import {spendEnergy} from './energy-budget.js';
import {advanceEnvironment,configureEnvironment} from './automatic-environment.js';
import {foodProduction,ENVIRONMENT_DEFAULTS,validateEnvironmentSettings} from './environment-settings.js';
import {saveWorld,loadWorld} from './world-save.js';
import {worldAxial} from './navigation.js';
import {translateFoodGroup} from './food-island-evolution.js';
import {proposedIslandCount} from './environment-plan.js';
import {aggregateLifeCohorts} from './life-cohorts.js';
import {sensitivityDistributions} from './heritable-statistics.js';
import {productionCohorts} from './food-production-history.js';
const assert=(ok,message)=>{if(!ok)throw new Error(message);};
export const ENVIRONMENT_CHECKS=[
 {id:'v037-group-shape',label:'0.37 · Целый островок сохраняет форму переноса и запасы',run(){const w=new Evolution({population:1}),g=structuredClone(w.foodIslands.find(g=>g.kind==='island')),before=g.sources.map(worldAxial),stock=w.tiles.map(c=>c.food),used=new Set(g.sources.map(p=>`${p.x},${p.y}`)),m=translateFoodGroup(w,g,used,w.automaticEnvironment.random);if(m){const a=worldAxial(m.from),b=worldAxial(m.to);for(let i=0;i<g.sources.length;i++){const p=worldAxial(g.sources[i]);assert(p.q-before[i].q===b.q-a.q&&p.r-before[i].r===b.r-a.r,'Искажена форма');}}assert(w.tiles.every((c,i)=>c.food===stock[i]),'Перенесена пища');}},
 {id:'v037-genetic-statistics',label:'0.37 · Наследуемые значения живых и распределение чувствительностей',run(){const w=new Evolution({population:2}),r=w.lifeReport(),g=aggregateLifeCohorts(r).cohorts[0];assert(g.metrics.senseEnergy.count===2&&g.metrics.lifetime.count===0,'Неверный состав');const d=sensitivityDistributions(r.living,{start:0,end:100})[0];assert(d.count===2&&Math.abs(d.points.reduce((n,p)=>n+p.mean,0)-100)<1e-8,'Неверные доли');}},
 {id:'v037-production-integral',label:'0.37 · Выработка пищи усредняется по времени событий',run(){const p=productionCohorts([{tick:0,value:2},{tick:5,value:6}],10,10);assert(p.length===1&&p[0].mean===4,'Неверное среднее');}},
 {id:'environment-deficit',label:'0.36 · Неоплаченная энергия превращается в здоровье без второго штрафа',run(){const w=new Evolution({population:1}),a=w.agents[0];a.energy=0;spendEnergy(w,a,.36);assert(Math.abs(a.health-98.5)<1e-8&&w.stats.spent===0,'Оплата дефицита');}},
 {id:'environment-stages',label:'0.38 · Пять событий подготовки, сохранение пищи и выбранный минимум',run(){const w=new Evolution({population:1,automaticEnvironment:{preparationInterval:1,randomInterval:1}});for(let i=1;i<=12;i++){const stock=w.tiles.reduce((n,c)=>n+c.food,0);w.tick=i;w.subtick=i*10;advanceEnvironment(w);assert(w.tiles.reduce((n,c)=>n+c.food,0)===stock&&foodProduction(w)>=ENVIRONMENT_DEFAULTS.minimumRate-1e-9,'Потеря пищи/порог');}assert(w.automaticEnvironment.completedSteps===5,'Число ступеней');configureEnvironment(w,{enabled:false});configureEnvironment(w,{enabled:true});assert(w.automaticEnvironment.nextTick===w.tick+1,'Интервал');}},
 {id:'environment-save',label:'0.38 · Полный JSON-снимок точно продолжает мир и целевую автоматику',run(){const w=new Evolution({population:2,automaticEnvironment:{preparationInterval:1,randomInterval:2}});w.step();const r=loadWorld(JSON.parse(JSON.stringify(saveWorld(w))));w.step();r.step();assert(JSON.stringify(saveWorld(w))===JSON.stringify(saveWorld(r)),'Продолжение расходится');}},
 {id:'target-environment-preparation',label:'0.38 · Пятая ступень достигает числа источников и долгого периода',run(){const w=new Evolution({population:1,automaticEnvironment:{targetPeriod:130,minimumRate:1,preparationInterval:1}});for(let i=1;i<=5;i++){w.tick=i;w.subtick=i*10;assert(advanceEnvironment(w),'Событие не выполнено');}assert(w.foodSettings.sourceCount===300&&Math.abs(w.foodSettings.regrowInterval-130)<1e-8,'Цели не достигнуты');}},
 {id:'target-environment-fallback',label:'0.38 · На пределе числа источников корректируется период',run(){const w=new Evolution({population:1,automaticEnvironment:{targetSources:10,targetPeriod:10000,preparationInterval:1}});w.automaticEnvironment.completedSteps=4;w.tick=1;w.subtick=10;assert(advanceEnvironment(w),'Событие не выполнено');assert(w.foodSettings.sourceCount===384&&w.environmentChanges.at(-1).periodsAdjusted&&foodProduction(w)>=2-1e-8&&foodProduction(w)<=6+1e-8,'Коррекция не сохранила диапазон');}},
 {id:'target-environment-minimum',label:'0.38 · Минимум настраивается ниже двух и запрещает ноль',run(){assert(validateEnvironmentSettings({minimumRate:.5}).minimumRate===.5,'Минимум ограничен двойкой');let rejected=false;try{validateEnvironmentSettings({minimumRate:0});}catch{rejected=true;}assert(rejected,'Ноль принят');}},
 {id:'island-count-small',label:'0.38.1 · Одного островка не удерживает округление слабого шума',run(){let call=0;const random={next:()=>call++%2===0?1-Math.exp(-.5):0};assert(proposedIslandCount(1,100,random)===2,'Нет выхода из единицы');assert(proposedIslandCount(1,1,random)===1,'Превышено число источников');}},
 {id:'island-distance',label:'0.38.1 · Целый островок переносится на 5–20 гексов',run(){const g={id:1,kind:'island',centre:{x:20,y:20},sources:[{x:20,y:20}]},used=new Set(['20,20']),m=translateFoodGroup({tile:(x,y)=>({x,y,terrain:'land'})},g,used,{next:()=>0});assert(m,'Перенос не выполнен');const a=worldAxial(m.from),b=worldAxial(m.to),distance=Math.max(Math.abs(b.q-a.q),Math.abs(b.r-a.r),Math.abs(b.q+b.r-a.q-a.r));assert(distance>=5&&distance<=20,'Неверное расстояние');}},
];
